156	pub fn call_stats(cg: &CallGraph) -> serde_json::Value {
157	    crate::name_resolution::glob_stats::GLOBAL.reset();
158	
159	    use crate::resolution::{DropReason, ResolutionConfidence};
160	
161	    use crate::call_graph::MethodKind;
162	
163	    let mut kinds: BTreeMap<&'static str, usize> = BTreeMap::new();
164	    let mut demoted = 0usize;
165	    let mut total = 0usize;
166	    let (mut multi, mut external, mut import_ext, mut unknown) = (0usize, 0usize, 0usize, 0usize);
167	    // Phase-3 stratification (re-measure for slice scoping): split each kind by
168	    // confidence, and stratify NameOnly demotes by (recovery, method-kind). This
169	    // isolates the #2-addressable universe — a NameOnly demote from `combine_kind`'s
170	    // single-candidate arm is a *receiver-recovery* kind (TypedParam/ConstructorLocal/
171	    // FieldTyped/ReturnTyped/TypedLet…) on a *trait* method — from the R6SingleOwner
172	    // residue + TraitCha multi (recovery "none", not combine_kind) and the #4
173	    // wrapper-peel `clone` edges. NOTE: the #2 count is an UPPER bound — it still
174	    // includes `dyn Trait` / trait-scope receivers that Slice 1 must exclude.
175	    let mut kind_exact: BTreeMap<&'static str, usize> = BTreeMap::new();
176	    let mut kind_nameonly: BTreeMap<&'static str, usize> = BTreeMap::new();
177	    let mut nameonly_recovery_mk: BTreeMap<String, usize> = BTreeMap::new();
178	    let mut wrapper_peel_clone = 0usize;
179	    let mut r6_rust = 0usize;
180	    // Same-site Exact over-attribution: a call site that resolves to >1 callee all
181	    // at Exact (1.0). The dominant precision-FP class this surfaces is the
182	    // same-bare-name owner-key collision (e.g. two distinct `Foo` structs both
183	    // owning `Foo::make` conflate under the bare `("Foo","make")` key and BOTH
184	    // resolve Exact — see resolution.rs `owner_lookup_in_modules`). NameOnly
185	    // (TraitCha) fanout is excluded — those are already demoted, not full-confidence.
186	    let mut multi_target_exact_sites = 0usize;
