    let cycle_src = "pub use a::*;\npub mod a { pub use crate::b::*; }\npub mod b { pub use crate::a::*; }\nfn f(){ let _: Option<S>; }\n";
    let (res, snap, _, _) = single_file_resolve(cycle_src, "S>;", "S");
    assert_eq!(res.status, ResStatus::Poisoned);
