}

#[test]
fn glob_expand_distinct_targets_two_globs() {
    let src = "mod a { pub struct S; }\nmod b { pub struct S; }\npub use a::*;\npub use b::*;\nfn f(){ let _: Option<S>; }\n";
    let (res, snap, _, _) = single_file_resolve(src, "S>;", "S");

