if rib_present {
    let res = resolve_rib(graph, &rib, q, policy, guard);
    // SPIKE-ONLY instrumentation (throwaway measurement, not part of any
    // shipped slice): when the rib claimed the name but every candidate was
    // visibility-filtered (Unresolved), classify whether ALL of them are
    // *known*-hidden (vis_reaches Some(false)) vs at least one *undecidable*
    // (vis_reaches None, e.g. an unresolved pub(in) restrict). Pure
    // read-only classification — does not change `res` or any candidate.
    if res.status == ResStatus::Unresolved {
        let all_hidden = rib.iter().all(|&bidx| {
            let b = &graph.bindings[bidx];
            let trav = TraversalCtx {
                lookup_scope: Some(b.scope),
                via_glob: false,
                edge_kind: None,
            };
            matches!(
                policy.spike_member_visible_tri(b, q, &trav),
                GlobEdgeVis::Hidden
            )
        });
        if all_hidden {
            guard.stats().spike_record_member_hidden();
        } else {
            guard.stats().spike_record_member_undecidable();
        }
    }
    return (res, true);
}

